1473 	player := gs.Players[playerIdx]
1474 
1475 	if player.Library.IsEmpty() {
1476 		return nil, false, errors.New("library is empty")
1477 	}
1478 
1479 	card, err := player.Library.DrawCard()
1480 	if err != nil {
1481 		return nil, false, err
1482 	}
1483 
1484 	// Check if first draw this turn
1485 	isFirstDraw := !player.HasDrawnThisTurn
1486 	player.HasDrawnThisTurn = true
1487 
1488 	hasMiracle := card.MiracleData != nil && isFirstDraw
1489 
1490 	if hasMiracle {
1491 		card.MiracleData.IsFirstDraw = true
1492 	}
1493 
1494 	player.Hand.AddCard(card)
1495 
1496 	// Fire draw event
1497 	if gs.EventBus != nil {
1498 		gs.EventBus.Publish(CreateDrawEvent(card, playerIdx))
1499 	}
1500 
1501 	return card, hasMiracle, nil
1502 }

